            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows_by_name = {name: {row["version"]: row for row in rows}
                    for name, rows in packages.items()}
    choices = []
    for name in names:
        versions = [v for v in rows_by_name[name]
                    if v not in blocked.get(name, [])
                    and (name not in pins or pins[name] == v)]
        choices.append([-1] + versions)

    best_vector = None
    best_install = None
    for values in product(*choices):
        installed = dict(zip(names, values))
        if any(installed.get(name, -1) < 0 or
               not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        graph = {}
        valid = True
        for name, version in installed.items():
            if version < 0:
                continue
            deps = []
            for dep in rows_by_name[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = installed.get(target, -1)
                if target_version < 0 or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                deps.append(target)
            graph[name] = deps
            if not valid:
                break
        if not valid:
            continue
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if reachable != {n for n, v in installed.items() if v >= 0}:
            continue
        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            state[name] = 2
            return True
        if any(not visit(name) for name in reachable):
            continue
        order = names if name_order == "ascending" else list(reversed(names))
        vector = tuple(installed[n] for n in order)
        better = (best_vector is None or
                  (vector > best_vector if preference == "maximum" else vector < best_vector))
        if better:
            best_vector = vector
            best_install = {n: v for n, v in installed.items() if v >= 0}
    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        key = event.get("id", "anonymous:" + str(pos))
        rank = (event.get("revision", 0), pos)
        if key not in winners or rank > winners[key][0]:
            winners[key] = (rank, event)
    balances = dict(data.get("opening", {}))

    def rounded(num, den):
        if data["rounding"] == "half_up":
            return (num + den // 2) // den
        return num // den

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def quota_jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    options = [j for j in jobs if j["id"] not in blocked]
    if not mandatory.issubset({j["id"] for j in options}):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    best_combo = None
    for combo in combinations(options, k):
        ids = tuple(sorted(j["id"] for j in combo))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in combo:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        valid = True
        for group, (low, high) in data.get("quotas", {}).items():
            if not low <= counts.get(group, 0) <= high:
                valid = False
                break
        if not valid:
            continue
        events = []
        for job in combo:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        for _, delta in sorted(events, key=lambda x: (x[0], x[1])):
            active += delta
            if active > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(j["value"] for j in combo)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids, best_combo = value, ids, combo
    if best_combo is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    dist = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | bits.get(dest, 0)
                next_state = (dest, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, next_mask, left))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda d: dependency_solver(d, "maximum", "descending"),
    "component_02": lambda d: dependency_solver(d, "minimum", "descending"),
    "component_03": lambda d: dependency_solver(d, "maximum", "ascending"),
    "component_04": lambda d: dependency_solver(d, "minimum", "ascending"),
    "component_05": lambda d: dependency_solver(d, "maximum", "descending"),
    "component_06": ledger,
    "component_07": quota_jobs,
    "component_08": temporal_routes,
}
